import sys
from bisect import bisect_left


class Interval:
    __slots__ = ('l', 'r')

    def __init__(self, l, r):
        self.l = l
        self.r = r


def find(dp, value, index):
    for i in range(index - 2, -1, -1):
        lst = dp[i]
        if not lst:
            continue
        ls = [x.l for x in lst]
        pos = bisect_left(ls, value.l)
        if pos < len(lst) and lst[pos].l == value.l:
            if lst[pos].r >= value.r:
                return True
        else:
            ind = pos - 1
            if ind > 0:
                if lst[ind].r >= value.r:
                    return True
    return False


def main():
    data = sys.stdin.read().split()
    idx = 0

    def next_int():
        nonlocal idx
        val = int(data[idx])
        idx += 1
        return val

    n = next_int()
    k = next_int()

    l = [0] * k
    r = [0] * k
    for i in range(k):
        l[i] = next_int()
        r[i] = next_int()

    size = 2 * k + 1
    dp = [[] for _ in range(size)]
    dp[0].append(Interval(0, 0))

    prev = 0
    for i in range(k):
        nxt = [[] for _ in range(size)]

        delta = l[i] - prev
        for index in range(size):
            if index % 2 == 0:
                for interval in dp[index]:
                    interval.l += delta
                    interval.r += delta

        delta = r[i] - l[i]
        for ii in range(size):
            if ii % 2 == 0:
                for interval in dp[ii]:
                    nxt[ii].append(Interval(interval.l + delta, interval.r + delta))
                    nxt[ii + 1].append(Interval(interval.l, interval.r + delta))
                    nxt[ii + 2].append(Interval(interval.l, interval.r + delta))
            else:
                for interval in dp[ii]:
                    nxt[ii].append(Interval(interval.l, interval.r))
                    nxt[ii + 1].append(Interval(interval.l, interval.r + delta))
                    nxt[ii + 2].append(Interval(interval.l, interval.r + delta))

        prev = r[i]
        for index in range(size):
            dp[index].clear()

            pr = None
            for interval in sorted(nxt[index], key=lambda t: t.l):
                if interval.l > n:
                    break
                if pr is not None and pr.r >= interval.l:
                    pr.r = max(pr.r, interval.r)
                else:
                    if pr is not None and not find(dp, pr, index):
                        dp[index].append(pr)
                    pr = interval
            if pr is not None and not find(dp, pr, index):
                dp[index].append(pr)

    delta = 2 * n - prev
    for index in range(size):
        if index % 2 == 0:
            for interval in dp[index]:
                interval.l += delta
                interval.r += delta

    for i in range(size):
        for interval in dp[i]:
            if interval.l <= n and interval.r >= n:
                print("Full")
                print(i)
                return

    print("Hungry")


if __name__ == "__main__":
    main()
